def maximum_sum_divisible_by_three(nums):
    best=[0,float('-inf'),float('-inf')]
    for value in nums:
        previous=best[:]
        for remainder,total in enumerate(previous):best[(remainder+value)%3]=max(best[(remainder+value)%3],total+value)
    return best[0]

